local N = #CX
local function ss(e0, e1, x) local t = math.clamp((x - e0) / (e1 - e0), 0, 1) return t * t * (3 - 2 * t) end
local function samp(a, z)
	local f = math.clamp((Z_START - z) / DZS + 1, 1, N)
	local i = math.min(math.floor(f), N - 1); local t = f - i
	return a[i] * (1 - t) + a[i + 1] * t
end
local function stripY(x, z)                                   -- the rock's top strip height at (x, z), or nil
	if z > Z_START or z < -548.0 then return nil end
	local c = samp(CX, z); local east = x >= c; local d = math.abs(x - c)
	local rim = samp(east and RIME or RIMW, z); local top = samp(east and TOPE or TOPW, z)
	if d < rim - 0.3 or d > rim + 10 then return nil end
	local f = math.clamp((d - rim) / 10, 0, 1)
	return top - 2.5 * f * f
end
local tp = RaycastParams.new(); tp.FilterType = Enum.RaycastFilterType.Include; tp.FilterDescendantsInstances = {workspace.Terrain}; tp.IgnoreWater = true
local function aabb(m)
	local lo, hi = Vector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)
	for _, q in ipairs(m:GetDescendants()) do
		if q:IsA("BasePart") then
			local cf, s = q.CFrame, q.Size / 2
			local ext = Vector3.new(math.abs(cf.RightVector.X) * s.X + math.abs(cf.UpVector.X) * s.Y + math.abs(cf.LookVector.X) * s.Z,
				math.abs(cf.RightVector.Y) * s.X + math.abs(cf.UpVector.Y) * s.Y + math.abs(cf.LookVector.Y) * s.Z,
				math.abs(cf.RightVector.Z) * s.X + math.abs(cf.UpVector.Z) * s.Y + math.abs(cf.LookVector.Z) * s.Z)
			lo = lo:Min(cf.Position - ext); hi = hi:Max(cf.Position + ext)
		end
	end
	return lo, hi
end
local TF = workspace.SouthGorge.Trees
local moved, removed, big, maxmove = 0, 0, 0, 0
for _, m in ipairs(TF:GetChildren()) do
	local lo, hi = aabb(m)
	local x, z = (lo.X + hi.X) / 2, (lo.Z + hi.Z) / 2
	local hit = workspace:Raycast(Vector3.new(x, 300, z), Vector3.new(0, -600, 0), tp)
	local g = hit and hit.Position.Y or nil
	local sy = stripY(x, z)
	if sy and (not g or sy > g) then g = sy end
	if not g or g < 1.0 then m:Destroy(); removed += 1
	else
		local dy = (g - 0.15) - lo.Y
		if math.abs(dy) > 0.05 then
			m:PivotTo(m:GetPivot() + Vector3.new(0, dy, 0)); moved += 1
			maxmove = math.max(maxmove, math.abs(dy)); if math.abs(dy) > 1.5 then big += 1 end
		end
	end
end
print(string.format("QQ T6 trees re-seated: moved %d (max %.2f, >1.5: %d), removed %d, left %d", moved, maxmove, big, removed, #TF:GetChildren()))
print("QQ T6 DONE")
